tool_schemas.implementation:
def todoist_create_task(content, description=None, priority=None, todoist_project_id=None, todoist_section_id=None, parent_todoist_task_id=None, order_index=None, due=None, deadline=None, labels_todoist_ids=None, assignee_todoist_id=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        p = os.path.join(_DB, "todoist_request_logs.json")
        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limit_check():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_create_task",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(content, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be a string", field="content")
        if content.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must not be empty", field="content")

        if description is not None and not isinstance(description, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "description must be a string", field="description")
        if priority is not None and not isinstance(priority, int):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer", field="priority")
        if priority is not None and not (1 <= priority <= 4):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4", field="priority")
        if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0", field="order_index")
        if todoist_project_id is not None and not isinstance(todoist_project_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "todoist_project_id must be a string", field="todoist_project_id")
        if todoist_section_id is not None and not isinstance(todoist_section_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "todoist_section_id must be a string", field="todoist_section_id")
        if parent_todoist_task_id is not None and not isinstance(parent_todoist_task_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_todoist_task_id must be a string", field="parent_todoist_task_id")
        if due is not None and not isinstance(due, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "due must be an object", field="due")
        if deadline is not None and not isinstance(deadline, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "deadline must be an object", field="deadline")
        if labels_todoist_ids is not None:
            if not isinstance(labels_todoist_ids, list) or any(not isinstance(x, str) for x in labels_todoist_ids):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "labels_todoist_ids must be an array of strings", field="labels_todoist_ids")
        if assignee_todoist_id is not None and not isinstance(assignee_todoist_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assignee_todoist_id must be a string", field="assignee_todoist_id")

        projects = _load("todoist_projects.json")
        sections = _load("todoist_sections.json")
        tasks = _load("todoist_tasks.json")
        labels = _load("todoist_labels.json")
        if not isinstance(projects, list):
            projects = []
        if not isinstance(sections, list):
            sections = []
        if not isinstance(tasks, list):
            tasks = []
        if not isinstance(labels, list):
            labels = []

        # Resolve/validate project:
        resolved_project_id = todoist_project_id
        if resolved_project_id is None:
            # pick any non-deleted project as default context
            for p in projects:
                if isinstance(p, dict) and p.get("status") != "deleted" and isinstance(p.get("todoist_project_id"), str):
                    resolved_project_id = p.get("todoist_project_id")
                    break
            if resolved_project_id is None:
                _log("UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No available project context to create task")

        proj_row = None
        for p in projects:
            if isinstance(p, dict) and p.get("todoist_project_id") == resolved_project_id:
                proj_row = p
                break
        if proj_row is None or proj_row.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Referenced project not found", todoist_project_id=resolved_project_id)

        # Validate section if provided. IMPORTANT: relax strictness if section doesn't exist; treat it as null (best-effort).
        resolved_section_id = todoist_section_id
        sec_row = None
        if resolved_section_id is not None:
            for s in sections:
                if isinstance(s, dict) and s.get("todoist_section_id") == resolved_section_id:
                    sec_row = s
                    break
            if sec_row is None or sec_row.get("status") == "deleted":
                # best-effort: do not reject; ensure no task references a deleted section by dropping it
                resolved_section_id = None
                sec_row = None
            else:
                # enforce same-project only if we can verify; otherwise best-effort
                if isinstance(sec_row.get("todoist_project_id"), str) and sec_row.get("todoist_project_id") != resolved_project_id:
                    resolved_section_id = None
                    sec_row = None

        # Validate parent task if provided: if not found or deleted, drop it (best-effort) rather than reject.
        resolved_parent_id = parent_todoist_task_id
        parent_row = None
        if resolved_parent_id is not None:
            for t in tasks:
                if isinstance(t, dict) and t.get("todoist_task_id") == resolved_parent_id:
                    parent_row = t
                    break
            if parent_row is None or parent_row.get("status") == "deleted":
                resolved_parent_id = None
                parent_row = None
            else:
                # If parent exists, align this task's project/section with parent's project/section.
                ppid = parent_row.get("todoist_project_id")
                if isinstance(ppid, str) and ppid != resolved_project_id:
                    resolved_project_id = ppid
                    # re-check project exists and not deleted
                    proj_row = None
                    for p in projects:
                        if isinstance(p, dict) and p.get("todoist_project_id") == resolved_project_id:
                            proj_row = p
                            break
                    if proj_row is None or proj_row.get("status") == "deleted":
                        _log("NOT_FOUND")
                        return _err("NOT_FOUND", "Referenced parent task's project not found", todoist_project_id=resolved_project_id)
                # if parent has section, only keep section if it exists and matches the project
                parent_sec = parent_row.get("todoist_section_id")
                if isinstance(parent_sec, str):
                    ps = None
                    for s in sections:
                        if isinstance(s, dict) and s.get("todoist_section_id") == parent_sec:
                            ps = s
                            break
                    if ps is not None and ps.get("status") != "deleted" and ps.get("todoist_project_id") == resolved_project_id:
                        resolved_section_id = parent_sec
                    else:
                        resolved_section_id = None

        # Validate labels at write time: unknown/deleted label IDs are rejected.
        resolved_labels = labels_todoist_ids if labels_todoist_ids is not None else []
        if not isinstance(resolved_labels, list):
            resolved_labels = []
        active_label_ids = set()
        for l in labels:
            if isinstance(l, dict) and l.get("status") != "deleted" and isinstance(l.get("todoist_label_id"), str):
                active_label_ids.add(l.get("todoist_label_id"))
        bad = [x for x in resolved_labels if x not in active_label_ids]
        if bad:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "labels_todoist_ids contains unknown or deleted label ids", invalid_label_ids=bad)

        # Generate unique ids
        existing_internal_ids = {t.get("id") for t in tasks if isinstance(t, dict)}
        existing_upstream_ids = {t.get("todoist_task_id") for t in tasks if isinstance(t, dict)}

        def _new_internal(prefix):
            while True:
                cand = prefix + uuid.uuid4().hex[:24]
                if cand not in existing_internal_ids:
                    return cand

        def _new_upstream_numeric_str():
            # upstream ids are stringified numeric; choose max+1 when possible
            mx = 0
            for v in existing_upstream_ids:
                if isinstance(v, str) and v.isdigit():
                    mx = max(mx, int(v))
            cand = str(mx + 1 if mx > 0 else int(uuid.uuid4().int % 10_000_000_000))
            while cand in existing_upstream_ids:
                cand = str(int(cand) + 1)
            return cand

        now = _now_z()
        row = {
            "id": _new_internal("td_task_"),
            "todoist_task_id": _new_upstream_numeric_str(),
            "content": content,
            "description": description,
            "priority": priority if priority is not None else 1,
            "todoist_project_id": resolved_project_id,
            "todoist_section_id": resolved_section_id,
            "parent_todoist_task_id": resolved_parent_id,
            "order_index": order_index if order_index is not None else 0,
            "due": due,
            "deadline": deadline,
            "labels_todoist_ids": resolved_labels,
            "assignee_todoist_id": assignee_todoist_id,
            "url": None,
            "status": "active",
            "completed_at": None,
            "deleted_at": None,
            "quick_add_raw": None,
            "quick_add_parse_result": None,
            "created_at": now,
            "updated_at": now
        }

        tasks.append(row)
        _save("todoist_tasks.json", tasks)

        _log("OK")
        return {"task": row}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def todoist_quick_add_task(quick_add_raw, todoist_project_id=None, todoist_section_id=None, parent_todoist_task_id=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_service_files():
        os.makedirs(_DB, exist_ok=True)
        if not os.path.exists(os.path.join(_DB, "todoist_request_logs.json")):
            _save("todoist_request_logs.json", [])
        if not os.path.exists(os.path.join(_DB, "todoist_usage_counters.json")):
            _save("todoist_usage_counters.json", [])

    def _log_request(endpoint, status):
        _ensure_service_files()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({"id": "td_rl_" + uuid.uuid4().hex[:16], "endpoint": endpoint, "status": status, "latency_ms": latency_ms, "timestamp": _now_z()})
        _save("todoist_request_logs.json", logs)

        counters = _load("todoist_usage_counters.json")
        if not isinstance(counters, list):
            counters = []
        today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        row = next((r for r in counters if isinstance(r, dict) and r.get("date") == today), None)
        if row is None:
            row = {"date": today, "read_calls": 0, "write_calls": 0}
            counters.append(row)
        row["write_calls"] = int(row.get("write_calls") or 0) + 1
        _save("todoist_usage_counters.json", counters)

    def _check_limits():
        _ensure_service_files()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if 0 <= (now_dt - ts).total_seconds() <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    try:
        lim = _check_limits()
        if lim:
            _log_request("todoist_quick_add_task", "error")
            return lim

        if not isinstance(quick_add_raw, str) or not quick_add_raw.strip():
            _log_request("todoist_quick_add_task", "error")
            return _err("VALIDATION_ERROR", "quick_add_raw is required and must be a non-empty string")

        for nm, val in (("todoist_project_id", todoist_project_id), ("todoist_section_id", todoist_section_id), ("parent_todoist_task_id", parent_todoist_task_id)):
            if val is not None and not isinstance(val, str):
                _log_request("todoist_quick_add_task", "error")
                return _err("VALIDATION_ERROR", f"{nm} must be a string")

        raw = quick_add_raw.strip()

        # Very small "best-effort" parser:
        # - Extract #Label tokens
        # - Extract p1..p4 for priority
        # - Remove those tokens from content
        tokens = raw.split()
        label_names = []
        pr = None
        kept = []
        for t in tokens:
            m = re.fullmatch(r"p([1-4])", t.strip().lower())
            if m:
                pr = int(m.group(1))
                continue
            if t.startswith("#") and len(t) > 1:
                label_names.append(t[1:])
                continue
            kept.append(t)
        content = " ".join(kept).strip()
        if not content:
            content = raw  # fall back

        projects = _load("todoist_projects.json")
        sections = _load("todoist_sections.json")
        labels = _load("todoist_labels.json")
        tasks = _load("todoist_tasks.json")
        if not isinstance(projects, list):
            projects = []
        if not isinstance(sections, list):
            sections = []
        if not isinstance(labels, list):
            labels = []
        if not isinstance(tasks, list):
            tasks = []

        # Resolve label names to upstream ids (only active labels). If unknown names, ignore (best-effort).
        name_to_up = {}
        for lb in labels:
            if not isinstance(lb, dict) or lb.get("status") == "deleted":
                continue
            if isinstance(lb.get("name"), str) and isinstance(lb.get("todoist_label_id"), str):
                name_to_up[lb["name"].lower()] = lb["todoist_label_id"]
        label_ids = []
        for nm in label_names:
            up = name_to_up.get(nm.lower())
            if up:
                label_ids.append(up)

        # Validate/resolve project/section/parent similarly to create_task, but keep "best-effort" behavior.
        resolved_project_id = todoist_project_id
        if resolved_project_id is not None:
            proj = next((p for p in projects if isinstance(p, dict) and p.get("todoist_project_id") == resolved_project_id and p.get("status") != "deleted"), None)
            if proj is None:
                _log_request("todoist_quick_add_task", "error")
                return _err("NOT_FOUND", "Project not found", todoist_project_id=resolved_project_id)

        if todoist_section_id is not None:
            sec = next((s for s in sections if isinstance(s, dict) and s.get("todoist_section_id") == todoist_section_id and s.get("status") != "deleted"), None)
            if sec is None:
                _log_request("todoist_quick_add_task", "error")
                return _err("NOT_FOUND", "Section not found", todoist_section_id=todoist_section_id)
            if isinstance(sec.get("todoist_project_id"), str) and sec.get("todoist_project_id"):
                resolved_project_id = sec.get("todoist_project_id")

        parent_upstream_id = None
        if parent_todoist_task_id is not None:
            parent_row = next((t for t in tasks if isinstance(t, dict) and t.get("todoist_task_id") == parent_todoist_task_id and t.get("status") != "deleted"), None)
            if parent_row is None:
                parent_row = next((t for t in tasks if isinstance(t, dict) and t.get("id") == parent_todoist_task_id and t.get("status") != "deleted"), None)
            if parent_row is None:
                _log_request("todoist_quick_add_task", "error")
                return _err("NOT_FOUND", "Parent task not found", parent_todoist_task_id=parent_todoist_task_id)
            parent_upstream_id = parent_row.get("todoist_task_id")
            if isinstance(parent_row.get("todoist_project_id"), str) and parent_row.get("todoist_project_id"):
                resolved_project_id = parent_row.get("todoist_project_id")
            if parent_row.get("todoist_section_id") is not None:
                todoist_section_id = parent_row.get("todoist_section_id")

        # If still no project context, pick any existing non-deleted project (so well-formed call is serviceable)
        if resolved_project_id is None:
            any_proj = next((p for p in projects if isinstance(p, dict) and p.get("status") != "deleted" and isinstance(p.get("todoist_project_id"), str)), None)
            if any_proj is None:
                _log_request("todoist_quick_add_task", "error")
                return _err("UNAUTHORIZED", "No available workspace/project context to create tasks")
            resolved_project_id = any_proj.get("todoist_project_id")

        # Ensure resolved project exists and not deleted
        proj_ok = next((p for p in projects if isinstance(p, dict) and p.get("todoist_project_id") == resolved_project_id and p.get("status") != "deleted"), None)
        if proj_ok is None:
            _log_request("todoist_quick_add_task", "error")
            return _err("NOT_FOUND", "Project not found", todoist_project_id=resolved_project_id)

        now = _now_z()
        new_id = "td_task_" + uuid.uuid4().hex[:24]
        existing_up = {t.get("todoist_task_id") for t in tasks if isinstance(t, dict)}
        base = int(time.time() * 1000)
        up_id = str(base)
        while up_id in existing_up:
            base += 1
            up_id = str(base)

        parse_result = {
            "raw": raw,
            "parsed": {
                "content": content,
                "priority": pr,
                "labels": label_names,
            },
            "context": {
                "todoist_project_id": todoist_project_id,
                "todoist_section_id": todoist_section_id,
                "parent_todoist_task_id": parent_todoist_task_id,
            },
        }

        row = {
            "id": new_id,
            "todoist_task_id": up_id,
            "content": content,
            "description": None,
            "priority": pr if pr is not None else 1,
            "todoist_project_id": resolved_project_id,
            "todoist_section_id": todoist_section_id,
            "parent_todoist_task_id": parent_upstream_id,
            "order_index": 0,
            "due": None,
            "deadline": None,
            "labels_todoist_ids": label_ids,
            "assignee_todoist_id": None,
            "url": None,
            "status": "active",
            "completed_at": None,
            "deleted_at": None,
            "quick_add_raw": raw,
            "quick_add_parse_result": parse_result,
            "created_at": now,
            "updated_at": now,
        }

        tasks.append(row)
        _save("todoist_tasks.json", tasks)
        _log_request("todoist_quick_add_task", "ok")
        return {"task": row}
    except Exception as e:
        _log_request("todoist_quick_add_task", "error")
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))

def todoist_get_tasks(todoist_project_id=None, todoist_section_id=None, parent_todoist_task_id=None, assignee_todoist_id=None, label_todoist_id=None, status=None, q=None, limit=None, cursor=None, sort=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    reqlog_file = "todoist_request_log.json"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, meta=None):
        logs = _load(reqlog_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_req_" + hashlib.sha256((endpoint + _iso_now() + str(time.time())).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "status": status,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save(reqlog_file, logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        obj = {"offset": offset}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    try:
        # Validate
        for nm, val in [
            ("todoist_project_id", todoist_project_id),
            ("todoist_section_id", todoist_section_id),
            ("parent_todoist_task_id", parent_todoist_task_id),
            ("assignee_todoist_id", assignee_todoist_id),
            ("label_todoist_id", label_todoist_id),
            ("q", q),
            ("cursor", cursor),
            ("sort", sort),
            ("sort_order", sort_order),
        ]:
            if val is not None and not isinstance(val, str):
                _log("todoist_get_tasks", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{nm} must be a string")

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

        if status is not None and status not in ("active", "completed", "deleted"):
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status")

        if sort is not None and sort not in ("created_at", "updated_at", "order_index", "priority", "content", "completed_at"):
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort")

        if sort_order is None:
            sort_order = "asc"
        if sort_order not in ("asc", "desc"):
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order")

        offset = _parse_cursor(cursor)
        if offset is None:
            _log("todoist_get_tasks", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

        tasks = _load("todoist_tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        # Default status filter: active+completed
        if status is None:
            filtered = [t for t in tasks if isinstance(t, dict) and t.get("status") in ("active", "completed")]
        else:
            filtered = [t for t in tasks if isinstance(t, dict) and t.get("status") == status]

        # Apply filters
        if todoist_project_id is not None:
            filtered = [t for t in filtered if t.get("todoist_project_id") == todoist_project_id]
        if todoist_section_id is not None:
            filtered = [t for t in filtered if t.get("todoist_section_id") == todoist_section_id]
        if parent_todoist_task_id is not None:
            filtered = [t for t in filtered if t.get("parent_todoist_task_id") == parent_todoist_task_id]
        if assignee_todoist_id is not None:
            filtered = [t for t in filtered if t.get("assignee_todoist_id") == assignee_todoist_id]
        if label_todoist_id is not None:
            filtered = [t for t in filtered if isinstance(t.get("labels_todoist_ids"), list) and label_todoist_id in t.get("labels_todoist_ids")]

        if q is not None and q.strip():
            qq = q.strip().lower()
            def _match(t):
                c = str(t.get("content") or "").lower()
                d = str(t.get("description") or "").lower()
                return (qq in c) or (qq in d)
            filtered = [t for t in filtered if _match(t)]

        # Sorting: if sort provided use it, else stable sort by due then order_index then created_at
        def _due_key(t):
            due = t.get("due")
            if not isinstance(due, dict):
                return (1, "")
            # Prefer datetime then date string
            dt = due.get("datetime") or due.get("date") or due.get("string") or ""
            return (0, str(dt))

        reverse = (sort_order == "desc")
        if sort is None:
            filtered.sort(key=lambda t: (_due_key(t), int(t.get("order_index") or 0), str(t.get("created_at") or "")))
        else:
            def _k(t):
                v = t.get(sort)
                if v is None:
                    # Put None last in asc, first in desc by using a tuple
                    return (1, "")
                if isinstance(v, (int, float)):
                    return (0, v)
                return (0, str(v).lower() if sort == "content" else str(v))
            filtered.sort(key=_k, reverse=reverse)

        total = len(filtered)
        page = filtered[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _make_cursor(next_offset) if has_more else None

        _log("todoist_get_tasks", "ok", meta={"returned": len(page), "total": total, "has_more": has_more})
        return {
            "tasks": page,
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    except Exception as e:
        _log("todoist_get_tasks", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

