    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim

        if not isinstance(id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a string", id=id)
