def todoist_update_task(id, content=None, description=None, priority=None, todoist_project_id=None, todoist_section_id=None, parent_todoist_task_id=None, order_index=None, due=None, deadline=None, labels_todoist_ids=None, assignee_todoist_id=None, **_extra):
    import json, os, datetime, uuid, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        p = os.path.join(_DB, "todoist_request_logs.json")
        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limit_check():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_update_task",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a string", id=id)
        # Relax pattern if exists; otherwise validate strictly.
        if not re.match(r"^td_task_[A-Za-z0-9]+$", id):
            tasks_tmp = _load("todoist_tasks.json")
            if not isinstance(tasks_tmp, list):
                tasks_tmp = []
            if not any(isinstance(t, dict) and t.get("id") == id for t in tasks_tmp):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "id does not match required pattern", id=id)

        if content is not None and (not isinstance(content, str) or content.strip() == ""):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be a non-empty string", field="content")
        if description is not None and not isinstance(description, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "description must be a string", field="description")
        if priority is not None and (not isinstance(priority, int) or not (1 <= priority <= 4)):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4", field="priority")
        if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0", field="order_index")
        if todoist_project_id is not None and not isinstance(todoist_project_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "todoist_project_id must be a string", field="todoist_project_id")
        if todoist_section_id is not None and not isinstance(todoist_section_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "todoist_section_id must be a string", field="todoist_section_id")
        if parent_todoist_task_id is not None and not isinstance(parent_todoist_task_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_todoist_task_id must be a string", field="parent_todoist_task_id")
        if due is not None and not isinstance(due, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "due must be an object", field="due")
        if deadline is not None and not isinstance(deadline, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "deadline must be an object", field="deadline")
        if labels_todoist_ids is not None:
            if not isinstance(labels_todoist_ids, list) or any(not isinstance(x, str) for x in labels_todoist_ids):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "labels_todoist_ids must be an array of strings", field="labels_todoist_ids")
        if assignee_todoist_id is not None and not isinstance(assignee_todoist_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assignee_todoist_id must be a string", field="assignee_todoist_id")

        projects = _load("todoist_projects.json")
        sections = _load("todoist_sections.json")
        tasks = _load("todoist_tasks.json")
        labels = _load("todoist_labels.json")
        if not isinstance(projects, list):
            projects = []
        if not isinstance(sections, list):
            sections = []
        if not isinstance(tasks, list):
            tasks = []
        if not isinstance(labels, list):
            labels = []

        idx = None
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("id") == id:
                idx = i
                break
        if idx is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", id=id)

        row = tasks[idx]
        if row.get("status") == "deleted":
            _log("CONFLICT")
            return _err("CONFLICT", "Cannot update a deleted task", id=id, status="deleted")

        # Prepare target refs (validate; best-effort for unknown section/parent by dropping them)
        target_project = todoist_project_id if todoist_project_id is not None else row.get("todoist_project_id")
        target_section = todoist_section_id if todoist_section_id is not None else row.get("todoist_section_id")
        target_parent = parent_todoist_task_id if parent_todoist_task_id is not None else row.get("parent_todoist_task_id")

        # project must exist and not be deleted
        proj_row = None
        for p in projects:
            if isinstance(p, dict) and p.get("todoist_project_id") == target_project:
                proj_row = p
                break
        if proj_row is None or proj_row.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Referenced project not found", todoist_project_id=target_project)

        # parent if provided must exist and not deleted; if not found, drop it (best-effort) rather than reject
        if target_parent is not None:
            ptask = None
            for t in tasks:
                if isinstance(t, dict) and t.get("todoist_task_id") == target_parent and t.get("status") != "deleted":
                    ptask = t
                    break
            if ptask is None:
                target_parent = None
            else:
                # align project/section with parent when possible
                ppid = ptask.get("todoist_project_id")
                if isinstance(ppid, str):
                    target_project = ppid
                    proj_row = None
                    for p in projects:
                        if isinstance(p, dict) and p.get("todoist_project_id") == target_project:
                            proj_row = p
                            break
                    if proj_row is None or proj_row.get("status") == "deleted":
                        _log("NOT_FOUND")
                        return _err("NOT_FOUND", "Referenced parent task's project not found", todoist_project_id=target_project)
                psec = ptask.get("todoist_section_id")
                if isinstance(psec, str):
                    target_section = psec

        # section if provided: if unknown/deleted, set to null; if belongs to different project, set to null
        if target_section is not None:
            sec_row = None
            for s in sections:
                if isinstance(s, dict) and s.get("todoist_section_id") == target_section:
                    sec_row = s
                    break
            if sec_row is None or sec_row.get("status") == "deleted":
                target_section = None
            else:
                if isinstance(sec_row.get("todoist_project_id"), str) and sec_row.get("todoist_project_id") != target_project:
                    target_section = None

        # labels validation (reject unknown/deleted)
        if labels_todoist_ids is not None:
            active_label_ids = set()
            for l in labels:
                if isinstance(l, dict) and l.get("status") != "deleted" and isinstance(l.get("todoist_label_id"), str):
                    active_label_ids.add(l.get("todoist_label_id"))
            bad = [x for x in labels_todoist_ids if x not in active_label_ids]
            if bad:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "labels_todoist_ids contains unknown or deleted label ids", invalid_label_ids=bad)

        changed = False
        if content is not None and content != row.get("content"):
            row["content"] = content
            changed = True
        if description is not None and description != row.get("description"):
            row["description"] = description
            changed = True
        if priority is not None and priority != row.get("priority"):
            row["priority"] = priority
            changed = True
        if due is not None or (due is None and "due" in _extra):  # do not support explicit null via schema; ignore
            if due is not None and due != row.get("due"):
                row["due"] = due
                changed = True
        if deadline is not None or (deadline is None and "deadline" in _extra):
            if deadline is not None and deadline != row.get("deadline"):
                row["deadline"] = deadline
                changed = True
        if labels_todoist_ids is not None and labels_todoist_ids != row.get("labels_todoist_ids"):
            row["labels_todoist_ids"] = labels_todoist_ids
            changed = True
        if assignee_todoist_id is not None and assignee_todoist_id != row.get("assignee_todoist_id"):
            row["assignee_todoist_id"] = assignee_todoist_id
            changed = True
        if order_index is not None and order_index != row.get("order_index"):
            row["order_index"] = order_index
            changed = True

        # movement fields
        if target_project != row.get("todoist_project_id"):
            row["todoist_project_id"] = target_project
            changed = True
        if target_section != row.get("todoist_section_id"):
            row["todoist_section_id"] = target_section
            changed = True
        if target_parent != row.get("parent_todoist_task_id"):
            row["parent_todoist_task_id"] = target_parent
            changed = True

        if not changed:
            # no-op update still returns current row (idempotent), but must be observable via logs only.
            _log("OK")
            return {"task": row}

        row["updated_at"] = _now_z()
        tasks[idx] = row
        _save("todoist_tasks.json", tasks)

        _log("OK")
        return {"task": row}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

