            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_delete_task",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    def _collect_descendants(tasks, root_todoist_task_id):
        # returns indices of all tasks (including root) whose todoist_task_id chains from root
        id_to_children = {}
        for i, t in enumerate(tasks):
            if not isinstance(t, dict):
                continue
            pid = t.get("parent_todoist_task_id")
            if isinstance(pid, str):
                id_to_children.setdefault(pid, []).append(i)

        # find root indices by todoist_task_id
        roots = []
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("todoist_task_id") == root_todoist_task_id:
                roots.append(i)

        res = set()
        stack = []
        for ri in roots:
            stack.append(ri)
        while stack:
            i = stack.pop()
            if i in res:
                continue
            res.add(i)
            tid = tasks[i].get("todoist_task_id")
            if isinstance(tid, str):
                for ci in id_to_children.get(tid, []):
                    stack.append(ci)
        return sorted(res)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a string", id=id)
        if not re.match(r"^td_task_[A-Za-z0-9]+$", id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id does not match required pattern", id=id)

        tasks = _load("todoist_tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        idx = None
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("id") == id:
                idx = i
                break
        if idx is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", id=id)

        row = tasks[idx]
        if row.get("status") == "deleted":
            _log("CONFLICT")
            return _err("CONFLICT", "Task already deleted", id=id)

        now = _now_z()
        root_upstream = row.get("todoist_task_id")
        if not isinstance(root_upstream, str):
            # still delete the row itself (cannot cascade)
            root_upstream = None

        # cascade soft-delete descendants as well
        to_delete_indices = [idx]
        if root_upstream is not None:
            to_delete_indices = _collect_descendants(tasks, root_upstream)

        for i in to_delete_indices:
            t = tasks[i]
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            # lifecycle: active/completed -> deleted allowed
            t["status"] = "deleted"
            t["deleted_at"] = now
            t["completed_at"] = None  # constraint: status != completed implies completed_at null
            t["updated_at"] = now
            tasks[i] = t

        _save("todoist_tasks.json", tasks)

        # return the originally requested task in deleted state
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == id:
                row = t
                break

        _log("OK")
        return {"task": row, "cascade_deleted_count": len(to_delete_indices)}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

