            "endpoint": "todoist_complete_task",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a string", id=id)
        if not re.match(r"^td_task_[A-Za-z0-9]+$", id):
