def todoist_search_tasks(query, todoist_project_id=None, todoist_section_id=None, status=None, labels_todoist_ids=None, assignee_todoist_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return None
        s = cur.strip()
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"=" * (-len(s) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and obj.get("v") == 1 and isinstance(obj.get("o"), int) and obj["o"] >= 0:
                return obj["o"]
        except Exception:
            pass
        if s.isdigit():
            return int(s)
        return None

    def _make_cursor(offset):
        obj = {"v": 1, "o": int(offset)}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # usage log (best-effort, optional collection)
    def _log(endpoint, status_code, detail=None):
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "status": status_code,
                "detail": detail,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now(),
            }
        )
        _save("todoist_request_logs.json", logs)

    # ---- validation
    if not _is_str(query) or not query.strip():
        _log("todoist_search_tasks", "error", "empty_query")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if todoist_project_id is not None and not _is_str(todoist_project_id):
        _log("todoist_search_tasks", "error", "bad_project_id")
        return _err("VALIDATION_ERROR", "todoist_project_id must be a string")
    if todoist_section_id is not None and not _is_str(todoist_section_id):
        _log("todoist_search_tasks", "error", "bad_section_id")
        return _err("VALIDATION_ERROR", "todoist_section_id must be a string")
    if assignee_todoist_id is not None and not _is_str(assignee_todoist_id):
        _log("todoist_search_tasks", "error", "bad_assignee_id")
        return _err("VALIDATION_ERROR", "assignee_todoist_id must be a string")

    if status is not None:
        if not _is_str(status) or status not in ("active", "completed", "deleted"):
            _log("todoist_search_tasks", "error", "bad_status")
            return _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("todoist_search_tasks", "error", "bad_limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    offset = _parse_cursor(cursor)
    if offset is None:
        _log("todoist_search_tasks", "error", "bad_cursor")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    if sort_by is None:
        sort_by = "created_at"
    if not _is_str(sort_by) or sort_by not in ("created_at", "updated_at", "order_index", "priority", "completed_at"):
        _log("todoist_search_tasks", "error", "bad_sort_by")
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, order_index, priority, completed_at")

    if sort_order is None:
        sort_order = "asc"
    if not _is_str(sort_order) or sort_order not in ("asc", "desc"):
        _log("todoist_search_tasks", "error", "bad_sort_order")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    if labels_todoist_ids is not None:
        if not isinstance(labels_todoist_ids, list) or any(not _is_str(x) for x in labels_todoist_ids):
            _log("todoist_search_tasks", "error", "bad_labels")
            return _err("VALIDATION_ERROR", "labels_todoist_ids must be an array of strings")
        # validate label existence & not deleted (write-time rule; for filter, still validate)
        labels = _load("todoist_labels.json")
        active_label_ids = {l.get("todoist_label_id") for l in labels if isinstance(l, dict) and l.get("status") != "deleted"}
        for lid in labels_todoist_ids:
            if lid not in active_label_ids:
                _log("todoist_search_tasks", "error", "label_not_found_or_deleted")
                return _err("VALIDATION_ERROR", f"label id {lid} does not exist or is deleted", label_id=lid)

    # validate optional scoping entities exist and are not deleted
    projects = _load("todoist_projects.json")
    sections = _load("todoist_sections.json")
    tasks = _load("todoist_tasks.json")

    project_row = None
    if todoist_project_id is not None:
        for p in projects:
            if isinstance(p, dict) and p.get("todoist_project_id") == todoist_project_id:
                project_row = p
                break
        if project_row is None or project_row.get("status") == "deleted":
            _log("todoist_search_tasks", "error", "project_not_found")
            return _err("NOT_FOUND", "project not found", todoist_project_id=todoist_project_id)

    section_row = None
    if todoist_section_id is not None:
        for s in sections:
            if isinstance(s, dict) and s.get("todoist_section_id") == todoist_section_id:
                section_row = s
                break
        if section_row is None or section_row.get("status") == "deleted":
            _log("todoist_search_tasks", "error", "section_not_found")
            return _err("NOT_FOUND", "section not found", todoist_section_id=todoist_section_id)
        if todoist_project_id is not None and section_row.get("todoist_project_id") != todoist_project_id:
            _log("todoist_search_tasks", "error", "section_project_mismatch")
            return _err("VALIDATION_ERROR", "todoist_section_id does not belong to todoist_project_id")

    q = query.strip().lower()

    def _task_text(t):
        c = t.get("content") or ""
        d = t.get("description") or ""
        return (str(c) + "\n" + str(d)).lower()

    # ---- filter
    out = []
    for t in tasks:
        if not isinstance(t, dict):
            continue

        st = t.get("status")
        if status is None:
            if st == "deleted":
                continue
        else:
            if st != status:
                continue

        if todoist_project_id is not None and t.get("todoist_project_id") != todoist_project_id:
            continue
        if todoist_section_id is not None and t.get("todoist_section_id") != todoist_section_id:
            continue
        if assignee_todoist_id is not None and t.get("assignee_todoist_id") != assignee_todoist_id:
            continue
        if labels_todoist_ids is not None:
            tl = t.get("labels_todoist_ids")
            if not isinstance(tl, list):
                continue
            sset = set(str(x) for x in tl)
            if any(lid not in sset for lid in labels_todoist_ids):
                continue

        if q not in _task_text(t):
            continue

        out.append(t)

    # ---- sort
    def _dt_key(v):
        if v is None:
            return ""
        return str(v)

    def _sort_key(t):
        v = t.get(sort_by)
        if sort_by in ("created_at", "updated_at", "completed_at"):
            v = _dt_key(v)
        elif sort_by in ("order_index", "priority"):
            try:
                v = int(v)
            except Exception:
                v = 0
        return (v, _dt_key(t.get("created_at")), str(t.get("id") or ""))

    reverse = sort_order == "desc"
    try:
        out.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # if caller-provided data has weird types, fall back to created_at stable ordering
        out.sort(key=lambda t: (_dt_key(t.get("created_at")), str(t.get("id") or "")))

    total = len(out)
    page = out[offset : offset + limit]
    next_offset = offset + len(page)
    next_cursor = _make_cursor(next_offset) if next_offset < total else None

    resp = {
        "tasks": page,
        "total": total,
