        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limit_check():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_move_task",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    def _collect_descendants_indices(tasks, root_todoist_task_id):
        id_to_children = {}
        for i, t in enumerate(tasks):
            if not isinstance(t, dict):
                continue
            pid = t.get("parent_todoist_task_id")
            if isinstance(pid, str):
                id_to_children.setdefault(pid, []).append(i)
        roots = []
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("todoist_task_id") == root_todoist_task_id:
                roots.append(i)
        res = set()
        stack = roots[:]
        while stack:
            i = stack.pop()
            if i in res:
                continue
            res.add(i)
            tid = tasks[i].get("todoist_task_id")
            if isinstance(tid, str):
                stack.extend(id_to_children.get(tid, []))
        return sorted(res)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(todoist_task_id, str) or todoist_task_id.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "todoist_task_id must be a non-empty string", todoist_task_id=todoist_task_id)

        dests = [todoist_project_id is not None, todoist_section_id is not None, parent_todoist_task_id is not None]
        if sum(1 for x in dests if x) != 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide exactly one destination field", fields=["todoist_project_id", "todoist_section_id", "parent_todoist_task_id"])

        projects = _load("todoist_projects.json")
        sections = _load("todoist_sections.json")
        tasks = _load("todoist_tasks.json")
        if not isinstance(projects, list):
            projects = []
        if not isinstance(sections, list):
            sections = []
        if not isinstance(tasks, list):
            tasks = []

        root_idx = None
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and t.get("todoist_task_id") == todoist_task_id:
                root_idx = i
                break
        if root_idx is None or tasks[root_idx].get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", todoist_task_id=todoist_task_id)

        root = tasks[root_idx]

        target_project = root.get("todoist_project_id")
        target_section = None
        target_parent = None

        if todoist_project_id is not None:
            target_project = todoist_project_id
            target_section = None
            target_parent = None
        elif todoist_section_id is not None:
            # validate section exists and not deleted; derive project from section
            sec = None
            for s in sections:
                if isinstance(s, dict) and s.get("todoist_section_id") == todoist_section_id and s.get("status") != "deleted":
                    sec = s
                    break
            if sec is None:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Section not found", todoist_section_id=todoist_section_id)
            target_section = todoist_section_id
            target_project = sec.get("todoist_project_id")
            target_parent = None
        else:
            # parent task destination
            pt = None
            for t in tasks:
                if isinstance(t, dict) and t.get("todoist_task_id") == parent_todoist_task_id and t.get("status") != "deleted":
                    pt = t
                    break
            if pt is None:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Parent task not found", parent_todoist_task_id=parent_todoist_task_id)
            target_parent = parent_todoist_task_id
            target_project = pt.get("todoist_project_id")
            # if parent has section and is valid, inherit it; else null
            psec = pt.get("todoist_section_id")
            if isinstance(psec, str):
                sec = None
                for s in sections:
                    if isinstance(s, dict) and s.get("todoist_section_id") == psec and s.get("status") != "deleted" and s.get("todoist_project_id") == target_project:
                        sec = s
                        break
                target_section = psec if sec is not None else None
            else:
                target_section = None

        # validate target project exists and not deleted
        proj = None
        for p in projects:
            if isinstance(p, dict) and p.get("todoist_project_id") == target_project:
                proj = p
                break
        if proj is None or proj.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Project not found", todoist_project_id=target_project)

        # if section set, it must belong to target project
        if target_section is not None:
            sec = None
            for s in sections:
                if isinstance(s, dict) and s.get("todoist_section_id") == target_section and s.get("status") != "deleted":
                    sec = s
                    break
            if sec is None or sec.get("todoist_project_id") != target_project:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Section must belong to the same project as the task", todoist_section_id=target_section, todoist_project_id=target_project)

        # apply move to task + descendants
        now = _now_z()
        indices = _collect_descendants_indices(tasks, todoist_task_id)
        for i in indices:
            t = tasks[i]
            if not isinstance(t, dict) or t.get("status") == "deleted":
                continue
            t["todoist_project_id"] = target_project
            # only root gets parent/section set directly per request; descendants keep their own parent relationship
            if i == root_idx:
                t["todoist_section_id"] = target_section
                t["parent_todoist_task_id"] = target_parent
            else:
                # if moving across projects, keep section only if still valid in target project; otherwise null
                if t.get("todoist_section_id") is not None:
                    sec_ok = False
                    for s in sections:
                        if isinstance(s, dict) and s.get("todoist_section_id") == t.get("todoist_section_id") and s.get("status") != "deleted" and s.get("todoist_project_id") == target_project:
                            sec_ok = True
                            break
                    if not sec_ok:
                        t["todoist_section_id"] = None
            t["updated_at"] = now
            tasks[i] = t

        _save("todoist_tasks.json", tasks)

        moved = tasks[root_idx]
        _log("OK")
        return {"task": moved, "moved_descendant_count": max(0, len(indices) - 1)}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

