            target_parent = parent_todoist_task_id
            target_project = pt.get("todoist_project_id")
            psec = pt.get("todoist_section_id")
            if isinstance(psec, str):
                sec = None
                for s in sections:
                    if isinstance(s, dict) and s.get("todoist_section_id") == psec and s.get("status") != "deleted" and s.get("todoist_project_id") == target_project:
                        sec = s
                        break
                target_section = psec if sec is not None else None

        proj = None
        for p in projects:
            if isinstance(p, dict) and p.get("todoist_project_id") == target_project:
                proj = p
                break
        if proj is None or proj.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Project not found", todoist_project_id=target_project)

        if target_section is not None:
            sec = None
            for s in sections:
                if isinstance(s, dict) and s.get("todoist_section_id") == target_section and s.get("status") != "deleted":
                    sec = s
                    break
            if sec is None or sec.get("todoist_project_id") != target_project:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Section must belong to the same project as the task", todoist_section_id=target_section, todoist_project_id=target_project)

        # Apply per task; atomic per task (per spec). We'll collect results and errors.
        now = _now_z()
        results = []
        errors = []

        # map upstream id -> root index
        up_to_idx = {}
        for i, t in enumerate(tasks):
            if isinstance(t, dict) and isinstance(t.get("todoist_task_id"), str):
                up_to_idx[t.get("todoist_task_id")] = i

        for tid in todoist_task_ids:
            root_idx = up_to_idx.get(tid)
            if root_idx is None or not isinstance(tasks[root_idx], dict) or tasks[root_idx].get("status") == "deleted":
                errors.append(_err("NOT_FOUND", "Task not found", todoist_task_id=tid))
                continue

            # compute indices to update for this root
            indices = _collect_descendants_indices(tasks, tid)

            # apply move
            for i in indices:
                t = tasks[i]
                if not isinstance(t, dict) or t.get("status") == "deleted":
                    continue
                t["todoist_project_id"] = target_project
                if i == root_idx:
                    t["todoist_section_id"] = target_section
                    t["parent_todoist_task_id"] = target_parent
                else:
                    if t.get("todoist_section_id") is not None:
                        sec_ok = False
                        for s in sections:
                            if isinstance(s, dict) and s.get("todoist_section_id") == t.get("todoist_section_id") and s.get("status") != "deleted" and s.get("todoist_project_id") == target_project:
                                sec_ok = True
                                break
                        if not sec_ok:
                            t["todoist_section_id"] = None
                t["updated_at"] = now
                tasks[i] = t

            results.append({"task": tasks[root_idx], "moved_descendant_count": max(0, len(indices) - 1)})

        if not results and errors:
            # no success without effect
            _save("todoist_tasks.json", tasks)  # no-op safe
            _log("NOT_FOUND")
            return {"errors": [e["error"] for e in errors]}

        _save("todoist_tasks.json", tasks)
        _log("OK")
        return {"results": results, "errors": [e["error"] for e in errors], "moved_count": len(results)}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

