        # Base64 JSON cursor
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"=" * (-len(s) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict):
                return obj
        except Exception:
            return {"after_id": s}  # opaque fallback
        return {"after_id": s}

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if include_archived is None:
        include_archived = False
    if not isinstance(include_archived, bool):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_archived must be a boolean")

    if sort_by is None:
        sort_by = "order_index"
    if sort_by not in ("order_index", "name", "created_at", "updated_at"):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: order_index, name, created_at, updated_at")

    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    lim = _check_limits()
    if lim:
        _log_and_count(lim["error"]["code"])
        return lim

    projects = _load("todoist_projects.json")
    if not isinstance(projects, list):
        projects = []

    # Filter deleted always; optionally include archived
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("status") == "deleted":
            continue
        if not include_archived and p.get("status") != "active":
            continue
        rows.append(p)

    # Sort stable: primary requested, tie-breakers order_index then created_at
    def _key(p):
        v = p.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_ts(v) if isinstance(v, str) else None
            v2 = dt.timestamp() if dt else 0
        elif sort_by == "order_index":
            try:
                v2 = int(v)
            except Exception:
                v2 = 0
        elif sort_by == "name":
            v2 = (v or "")
            if not isinstance(v2, str):
                v2 = str(v2)
            v2 = v2.lower()
        else:
            v2 = v
        # tiebreakers
        try:
            oi = int(p.get("order_index") or 0)
        except Exception:
            oi = 0
        ca = _parse_ts(p.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (v2, oi, ca.timestamp(), p.get("id") or "")

    reverse = (sort_order == "desc")
    rows.sort(key=_key, reverse=reverse)

    # Cursor handling: accept after_id or offset
    start = 0
    cobj = _decode_cursor(cursor)
    if cobj:
        if isinstance(cobj, dict) and "offset" in cobj:
            off = cobj.get("offset")
            if isinstance(off, int) and off >= 0:
                start = off
        elif isinstance(cobj, dict) and "after_id" in cobj:
            aid = cobj.get("after_id")
            if isinstance(aid, str) and aid:
                idx = None
                for i, p in enumerate(rows):
                    if p.get("id") == aid:
                        idx = i
                        break
                if idx is not None:
                    start = idx + 1
                else:
                    # If unknown cursor id, treat as start-of-list (opaque behavior, not validation error)
                    start = 0

    page = rows[start : start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        # issue after_id cursor using the last internal id (opaque)
        next_cursor = _encode_cursor({"v": 1, "after_id": page[-1].get("id")})

    _log_and_count("ok")
    return {"projects": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

