        if not parent_todoist_project_id.strip():
            return _finalize(_err("VALIDATION_ERROR", "parent_todoist_project_id must be non-empty when provided."), "error")
        parent = next((p for p in projects if p.get("todoist_project_id") == parent_todoist_project_id), None)
        if not parent or parent.get("status") == "deleted":
            return _finalize(_err("NOT_FOUND", "Parent project not found."), "not_found")

    # Determine default order_index if not provided: append to end
    if order_index is None:
        max_idx = -1
        for p in projects:
            if p.get("status") != "deleted" and isinstance(p.get("order_index"), int):
                if p["order_index"] > max_idx:
                    max_idx = p["order_index"]
        order_index = max_idx + 1

    # Generate unique ids
    existing_upstream = {p.get("todoist_project_id") for p in projects if isinstance(p.get("todoist_project_id"), str)}
    existing_internal = {p.get("id") for p in projects if isinstance(p.get("id"), str)}

    def _gen_internal():
        return f"proj_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    def _gen_upstream():
        # numeric-string-like id
        return str(int(time.time()*1000)) + str(random.randint(100, 999))

    new_id = _gen_internal()
    while new_id in existing_internal:
        new_id = _gen_internal()

    new_todoist_project_id = _gen_upstream()
    while new_todoist_project_id in existing_upstream:
        new_todoist_project_id = _gen_upstream()

    row = {
        "id": new_id,
        "todoist_project_id": new_todoist_project_id,
