    _save("todoist_projects.json", projects)

    return _finalize({"project": row}, "ok")

def todoist_update_project(todoist_project_id, name=None, color=None, is_favorite=None, view_style=None, parent_todoist_project_id=None, order_index=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    reqlog_name = "todoist_request_log.json"
    reqlog = _load(reqlog_name)
    log_row = {
        "id": f"req_{int(time.time()*1000)}",
        "tool": "todoist_update_project",
        "timestamp": now,
        "status": "error",
        "latency_ms": None,
        "credential": None,
        "details": {"todoist_project_id": todoist_project_id, "status": status},
    }

    def _finalize(resp, status_str):
        log_row["status"] = status_str
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        reqlog.append(log_row)
        _save(reqlog_name, reqlog)
        return resp

    # Validation
    if not isinstance(todoist_project_id, str) or not todoist_project_id.strip():
        return _finalize(_err("VALIDATION_ERROR", "todoist_project_id is required and must be a non-empty string."), "error")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _finalize(_err("VALIDATION_ERROR", "name must be a non-empty string when provided."), "error")
    if color is not None and not isinstance(color, str):
        return _finalize(_err("VALIDATION_ERROR", "color must be a string."), "error")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        return _finalize(_err("VALIDATION_ERROR", "is_favorite must be a boolean."), "error")
    if view_style is not None and not isinstance(view_style, str):
        return _finalize(_err("VALIDATION_ERROR", "view_style must be a string."), "error")
    if parent_todoist_project_id is not None and not isinstance(parent_todoist_project_id, str):
        return _finalize(_err("VALIDATION_ERROR", "parent_todoist_project_id must be a string."), "error")
    if order_index is not None and (not isinstance(order_index, int) or order_index < 0):
        return _finalize(_err("VALIDATION_ERROR", "order_index must be an integer >= 0."), "error")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            return _finalize(_err("VALIDATION_ERROR", "status must be one of: active, archived, deleted."), "error")

    projects = _load("todoist_projects.json")
    proj = None
    for p in projects:
        if p.get("todoist_project_id") == todoist_project_id:
            proj = p
            break
    if not proj:
        return _finalize(_err("NOT_FOUND", "Project not found."), "not_found")

    if proj.get("status") == "deleted":
        return _finalize(_err("CONFLICT", "Cannot update a deleted project."), "conflict")

    # Parent validation/re-parenting
    if parent_todoist_project_id is not None:
        if parent_todoist_project_id.strip() == "":
            # allow explicitly clearing parent by sending empty string? treat as validation error
            return _finalize(_err("VALIDATION_ERROR", "parent_todoist_project_id must be non-empty when provided; omit to keep unchanged."), "error")
        if parent_todoist_project_id == todoist_project_id:
            return _finalize(_err("VALIDATION_ERROR", "A project cannot be its own parent."), "error")
        parent = next((pp for pp in projects if pp.get("todoist_project_id") == parent_todoist_project_id), None)
        if not parent or parent.get("status") == "deleted":
            return _finalize(_err("NOT_FOUND", "Parent project not found."), "not_found")

        # prevent cycles
        ancestors = set()
        cur = parent
        while cur and cur.get("parent_todoist_project_id"):
            pid = cur.get("parent_todoist_project_id")
            if pid in ancestors:
                break
            ancestors.add(pid)
            if pid == todoist_project_id:
                return _finalize(_err("VALIDATION_ERROR", "Re-parenting would create a cycle."), "error")
            cur = next((pp for pp in projects if pp.get("todoist_project_id") == pid), None)

    # Status transition validation (active <-> archived; deleted handled by delete tool ideally but supported here per description)
    if status is not None and status != proj.get("status"):
        allowed = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        cur_status = proj.get("status")
        if status not in allowed.get(cur_status, set()):
            return _finalize(_err("INVALID_TRANSITION", f"Cannot transition project from {cur_status} to {status}."), "invalid_transition")

    changed = False

    if name is not None and name.strip() != proj.get("name"):
        proj["name"] = name.strip()
        changed = True
    if color is not None and color != proj.get("color"):
        proj["color"] = color
        changed = True
    if is_favorite is not None and is_favorite != proj.get("is_favorite"):
        proj["is_favorite"] = is_favorite
        changed = True
    if view_style is not None and view_style != proj.get("view_style"):
        proj["view_style"] = view_style
        changed = True
    if parent_todoist_project_id is not None and parent_todoist_project_id != proj.get("parent_todoist_project_id"):
        proj["parent_todoist_project_id"] = parent_todoist_project_id
        changed = True
    if order_index is not None and order_index != proj.get("order_index"):
        proj["order_index"] = order_index
        changed = True

    # Apply status change (with constraints on deleted_at)
    if status is not None and status != proj.get("status"):
        proj["status"] = status
        changed = True
        if status == "deleted":
            proj["deleted_at"] = now
        else:
            proj["deleted_at"] = None

    if not changed:
        # No-op update still returns the row (idempotent), but it DID match a row (effect: none).
        # To avoid "success without effect" on mutation, refresh updated_at only if actual change.
        return _finalize({"project": proj}, "ok")

    proj["updated_at"] = now

    # If soft-deleted via update, cascade like delete_project rule
    if proj.get("status") == "deleted":
        sections = _load("todoist_sections.json")
        tasks = _load("todoist_tasks.json")
        for s in sections:
            if s.get("todoist_project_id") == todoist_project_id and s.get("status") != "deleted":
                s["status"] = "deleted"
                s["deleted_at"] = now
                s["updated_at"] = now
        for t in tasks:
            if t.get("todoist_project_id") == todoist_project_id and t.get("status") != "deleted":
                t["status"] = "deleted"
                t["deleted_at"] = now
                t["completed_at"] = None
                t["updated_at"] = now
        _save("todoist_sections.json", sections)
        _save("todoist_tasks.json", tasks)

    _save("todoist_projects.json", projects)
    return _finalize({"project": proj}, "ok")

