    if "deleted" not in allowed.get(cur_status, set()):
        return _finalize(_err("INVALID_TRANSITION", f"Cannot transition project from {cur_status} to deleted."), "invalid_transition")

    # Cascade in a "transaction": mutate in memory then persist
    sections = _load("todoist_sections.json")
