            t["status"] = "deleted"
            t["deleted_at"] = now
            # must satisfy constraint: status != completed implies completed_at is null
            t["completed_at"] = None
            t["updated_at"] = now

    _save("todoist_projects.json", projects)
    _save("todoist_sections.json", sections)
    _save("todoist_tasks.json", tasks)

