    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_service_files():
        try:
            os.makedirs(_DB, exist_ok=True)
        except Exception:
            return
        p = os.path.join(_DB, "todoist_request_logs.json")
        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])
        p2 = os.path.join(_DB, "todoist_usage_counters.json")
        if not os.path.exists(p2):
            _save("todoist_usage_counters.json", [])

    def _check_limits():
        _ensure_service_files()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-3000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts and 0 <= (now_dt - ts).total_seconds() <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _log_and_count(status_code):
        _ensure_service_files()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({"id": "td_rl_" + uuid.uuid4().hex[:16], "endpoint": "todoist_get_sections", "status": status_code, "latency_ms": latency_ms, "timestamp": _now_z()})
        _save("todoist_request_logs.json", logs)

        counters = _load("todoist_usage_counters.json")
        if not isinstance(counters, list):
            counters = []
        today = datetime.datetime.utcnow().date().isoformat()
        row = None
        for r in counters:
            if isinstance(r, dict) and r.get("date") == today:
                row = r
                break
        if row is None:
            row = {"date": today, "read_calls": 0, "write_calls": 0}
            counters.append(row)
        row["read_calls"] = int(row.get("read_calls") or 0) + 1
        _save("todoist_usage_counters.json", counters)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        s = cur.strip()
        if s.startswith("td_"):
            return {"after_id": s}
        if s.isdigit():
            return {"offset": int(s)}
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"=" * (-len(s) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict):
                return obj
        except Exception:
            return {"after_id": s}
        return {"after_id": s}

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    if todoist_project_id is not None and (not isinstance(todoist_project_id, str) or not todoist_project_id.strip()):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "todoist_project_id must be a non-empty string")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log_and_count("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "order_index"
    if sort not in ("order_index", "created_at", "updated_at", "name"):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: order_index, created_at, updated_at, name")

    if sort_direction is None:
        sort_direction = "asc"
    if sort_direction not in ("asc", "desc"):
        _log_and_count("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc")

    lim = _check_limits()
    if lim:
        _log_and_count(lim["error"]["code"])
        return lim

    projects = _load("todoist_projects.json")
    if not isinstance(projects, list):
        projects = []
    sections = _load("todoist_sections.json")
    if not isinstance(sections, list):
        sections = []

    if todoist_project_id is not None:
        proj = next((p for p in projects if isinstance(p, dict) and p.get("todoist_project_id") == todoist_project_id and p.get("status") != "deleted"), None)
        if proj is None:
            _log_and_count("NOT_FOUND")
            return _err("NOT_FOUND", "Project not found or deleted", todoist_project_id=todoist_project_id)

    rows = []
    for s in sections:
        if not isinstance(s, dict):
            continue
        if s.get("status") == "deleted":
            # by default, exclude deleted; include only if filter explicitly asks for deleted
            if status != "deleted":
                continue
        else:
            if status == "deleted":
                continue
        if todoist_project_id is not None and s.get("todoist_project_id") != todoist_project_id:
            continue
        # default behavior: only not-deleted if no status filter provided
        if status is None and s.get("status") == "deleted":
            continue
        rows.append(s)

    def _key(s):
        v = s.get(sort)
        if sort in ("created_at", "updated_at"):
            dt = _parse_ts(v) if isinstance(v, str) else None
            v2 = dt.timestamp() if dt else 0
        elif sort == "order_index":
            try:
                v2 = int(v)
            except Exception:
                v2 = 0
        elif sort == "name":
            vv = v or ""
            if not isinstance(vv, str):
                vv = str(vv)
            v2 = vv.lower()
        else:
            v2 = v
        # tiebreakers
        try:
            oi = int(s.get("order_index") or 0)
        except Exception:
            oi = 0
        ca = _parse_ts(s.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (v2, oi, ca.timestamp(), s.get("id") or "")

    rows.sort(key=_key, reverse=(sort_direction == "desc"))

    start = 0
    cobj = _decode_cursor(cursor)
    if cobj:
        if isinstance(cobj, dict) and "offset" in cobj:
            off = cobj.get("offset")
            if isinstance(off, int) and off >= 0:
                start = off
        elif isinstance(cobj, dict) and "after_id" in cobj:
            aid = cobj.get("after_id")
            if isinstance(aid, str) and aid:
                idx = None
                for i, s in enumerate(rows):
                    if s.get("id") == aid:
                        idx = i
                        break
                start = (idx + 1) if idx is not None else 0

    page = rows[start : start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        next_cursor = _encode_cursor({"v": 1, "after_id": page[-1].get("id")})

    _log_and_count("ok")
    return {"sections": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def todoist_create_section(todoist_project_id, name, order_index=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, ok):
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "todoist_create_section",
            "status": status_code,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # validation
    if not isinstance(todoist_project_id, str) or not todoist_project_id.strip():
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "todoist_project_id is required and must be a non-empty string")
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")
    if order_index is not None and not isinstance(order_index, int):
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "order_index must be an integer")
    if isinstance(order_index, int) and order_index < 0:
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "order_index must be >= 0")

    projects = _load("todoist_projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if p.get("todoist_project_id") == todoist_project_id and p.get("status") != "deleted"), None)
    if proj is None:
        _log("NOT_FOUND", False)
        return _err("NOT_FOUND", "Project not found", todoist_project_id=todoist_project_id)

    sections = _load("todoist_sections.json")
    if not isinstance(sections, list):
        sections = []

    # compute order_index if not provided: append within project among non-deleted and deleted too (keep stability)
    if order_index is None:
        max_idx = -1
        for s in sections:
            if s.get("todoist_project_id") == todoist_project_id:
                oi = s.get("order_index")
                if isinstance(oi, int) and oi > max_idx:
                    max_idx = oi
        order_index = max_idx + 1

    # generate unique ids
    def _new_internal_id(existing):
        while True:
            v = "sec_" + uuid.uuid4().hex
            if all(r.get("id") != v for r in existing):
                return v

    def _new_upstream_id(existing):
        # stringified numeric-like, but uniqueness is the main constraint
        existing_ids = {str(r.get("todoist_section_id")) for r in existing if r.get("todoist_section_id") is not None}
        # try time-based numeric string
        base = int(datetime.datetime.utcnow().timestamp() * 1000)
        for i in range(0, 10000):
            cand = str(base + i)
            if cand not in existing_ids:
                return cand
        # fallback uuid numeric-ish
        while True:
            cand = str(int(uuid.uuid4().int % (10**15)))
            if cand not in existing_ids:
                return cand

    todoist_section_id = _new_upstream_id(sections)
    row = {
        "id": _new_internal_id(sections),
        "todoist_section_id": todoist_section_id,
        "todoist_project_id": todoist_project_id,
        "name": name.strip(),
        "order_index": order_index,
        "status": "active",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    sections.append(row)
    _save("todoist_sections.json", sections)

    _log("OK", True)
    return {"section": row}

def todoist_update_section(todoist_section_id, name=None, order_index=None, todoist_project_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, ok):
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "todoist_update_section",
            "status": status_code,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # validation
    if not isinstance(todoist_section_id, str) or not todoist_section_id.strip():
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "todoist_section_id is required and must be a non-empty string")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if order_index is not None:
        if not isinstance(order_index, int):
            _log("VALIDATION_ERROR", False)
            return _err("VALIDATION_ERROR", "order_index must be an integer")
        if order_index < 0:
            _log("VALIDATION_ERROR", False)
            return _err("VALIDATION_ERROR", "order_index must be >= 0")
    if todoist_project_id is not None and (not isinstance(todoist_project_id, str) or not todoist_project_id.strip()):
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "todoist_project_id must be a non-empty string when provided")

    sections = _load("todoist_sections.json")
    if not isinstance(sections, list):
        sections = []
    idx = next((i for i, s in enumerate(sections) if s.get("todoist_section_id") == todoist_section_id), None)
    if idx is None:
        _log("NOT_FOUND", False)
        return _err("NOT_FOUND", "Section not found", todoist_section_id=todoist_section_id)

    section = sections[idx]
    if section.get("status") == "deleted":
        _log("CONFLICT", False)
        return _err("CONFLICT", "Cannot update a deleted section", todoist_section_id=todoist_section_id)

    # destination project validation if moving
    if todoist_project_id is not None and todoist_project_id != section.get("todoist_project_id"):
        projects = _load("todoist_projects.json")
        if not isinstance(projects, list):
            projects = []
        proj = next((p for p in projects if p.get("todoist_project_id") == todoist_project_id and p.get("status") != "deleted"), None)
        if proj is None:
            _log("NOT_FOUND", False)
            return _err("NOT_FOUND", "Destination project not found", todoist_project_id=todoist_project_id)

    # apply updates
    changed = False
    if name is not None and name.strip() != section.get("name"):
        section["name"] = name.strip()
        changed = True
    if order_index is not None and order_index != section.get("order_index"):
        section["order_index"] = order_index
        changed = True
    if todoist_project_id is not None and todoist_project_id != section.get("todoist_project_id"):
        old_project = section.get("todoist_project_id")
        section["todoist_project_id"] = todoist_project_id
        changed = True

        # integrity rule: tasks referencing this section must remain valid and belong to same project
        tasks = _load("todoist_tasks.json")
        if not isinstance(tasks, list):
            tasks = []
        # fail if any non-deleted task references this section but belongs to a different project than new
        for t in tasks:
            if t.get("status") == "deleted":
                continue
            if t.get("todoist_section_id") == todoist_section_id and t.get("todoist_project_id") != todoist_project_id:
                # Choose a safe behaviour: move those tasks' project too would be "move_task", not section move.
                # So refuse with CONFLICT.
                section["todoist_project_id"] = old_project
                _log("CONFLICT", False)
                return _err(
                    "CONFLICT",
                    "Cannot move section because existing tasks in the section belong to a different project; move tasks first",
                    todoist_section_id=todoist_section_id
                )

    if not changed:
        # no-success-without-effect: return current record (read) as OK because update endpoint in real services
        # is often idempotent; but we must not claim a mutation happened. Return the record with a flag.
        _log("OK", True)
        return {"section": section, "updated": False}

    section["updated_at"] = now
    sections[idx] = section
    _save("todoist_sections.json", sections)

    _log("OK", True)
    return {"section": section, "updated": True}

def todoist_delete_section(todoist_section_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, ok):
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "todoist_delete_section",
            "status": status_code,
            "ok": bool(ok),
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(todoist_section_id, str) or not todoist_section_id.strip():
        _log("VALIDATION_ERROR", False)
        return _err("VALIDATION_ERROR", "todoist_section_id is required and must be a non-empty string")

    sections = _load("todoist_sections.json")
    if not isinstance(sections, list):
        sections = []

    idx = next((i for i, s in enumerate(sections) if s.get("todoist_section_id") == todoist_section_id), None)
    if idx is None:
        _log("NOT_FOUND", False)
        return _err("NOT_FOUND", "Section not found", todoist_section_id=todoist_section_id)

    section = sections[idx]
    if section.get("status") == "deleted":
        # spec says CONFLICT if already deleted (even though some endpoints are idempotent; delete_section is not)
        _log("CONFLICT", False)
        return _err("CONFLICT", "Section already deleted", todoist_section_id=todoist_section_id)

    # transition active -> deleted
    section["status"] = "deleted"
    section["deleted_at"] = now
    section["updated_at"] = now
    sections[idx] = section

    # enforce "no task references a deleted section": null out todoist_section_id for tasks in this section
    tasks = _load("todoist_tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    touched = False
    for t in tasks:
        if t.get("todoist_section_id") == todoist_section_id and t.get("status") != "deleted":
            t["todoist_section_id"] = None
            t["updated_at"] = now
            touched = True

    _save("todoist_sections.json", sections)
    if touched:
        _save("todoist_tasks.json", tasks)

    _log("OK", True)
    return {"section": section, "tasks_updated": touched}

def todoist_create_label(name, color=None, order_index=None, is_favorite=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _as_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        return None

    def _log(endpoint, status, latency_ms, reason=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "reason": reason,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        # Best-effort limits backed by request_logs.json (if present).
        # If the collection doesn't exist yet, create it lazily.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        day_s = 86400
        # Conservative defaults
        per_minute = 120
        per_day_writes = 2000

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        daily_writes = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            age = (now - ts).total_seconds()
            if age <= window_s:
                recent += 1
            if age <= day_s and isinstance(r.get("endpoint"), str) and r.get("endpoint", "").startswith("todoist_") and (
                "create_" in r.get("endpoint", "") or "update_" in r.get("endpoint", "") or "delete_" in r.get("endpoint", "") or "move_" in r.get("endpoint", "") or "bulk_" in r.get("endpoint", "")
            ):
                daily_writes += 1

        if recent >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=per_minute, window_seconds=window_s)
        if endpoint in ("todoist_create_label", "todoist_update_label") and daily_writes >= per_day_writes:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded.", quota=per_day_writes, window_seconds=day_s)
        return None

    start = time.time()
    endpoint = "todoist_create_label"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _log(endpoint, "error", (time.time() - start) * 1000, reason=limit_err["error"]["code"])
        return limit_err

    # Ambient auth: no explicit credential parameter; accept if datastore is accessible.
    # If datastore is missing, it's still an accessible empty workspace.

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'name' must be a non-empty string.", field="name")

    if color is not None and not isinstance(color, str):
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'color' must be a string when provided.", field="color")

    if order_index is not None:
        oi = _as_int(order_index)
        if oi is None or oi < 0:
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'order_index' must be an integer >= 0 when provided.", field="order_index")
        order_index = oi

    if is_favorite is not None and not isinstance(is_favorite, bool):
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'is_favorite' must be a boolean when provided.", field="is_favorite")

    labels = _load("todoist_labels.json")
    if not isinstance(labels, list):
        labels = []

    # Enforce unique(name) where status != 'deleted'
    nm = name.strip()
    for r in labels:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "deleted" and isinstance(r.get("name"), str) and r["name"].strip().lower() == nm.lower():
            _log(endpoint, "error", (time.time() - start) * 1000, reason="CONFLICT")
            return _err("CONFLICT", "A non-deleted label with this name already exists.", field="name")

    # Determine defaults
    if order_index is None:
        max_oi = -1
        for r in labels:
            if isinstance(r, dict) and r.get("status") != "deleted" and isinstance(r.get("order_index"), int):
                if r["order_index"] > max_oi:
                    max_oi = r["order_index"]
        order_index = max_oi + 1

    if is_favorite is None:
        is_favorite = False

    # Create new unique upstream-ish ID (stringified numeric). Generate monotonically from existing numeric ids.
    max_tid = 0
    for r in labels:
        if not isinstance(r, dict):
            continue
        t = r.get("todoist_label_id")
