    def _log(endpoint, status_s, latency_ms, reason=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "reason": reason,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        per_minute = 240

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                recent += 1
        if recent >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=per_minute, window_seconds=window_s)
        return None

    def _as_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        return None

    def _decode_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return "__bad__"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return "__bad__"
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return "__bad__"
            return obj
        except Exception:
            return "__bad__"

    def _encode_cursor(offset, sort_f, sort_dir, filt):
        payload = {"offset": offset, "sort": sort_f, "sort_direction": sort_dir, "filter": filt}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    start = time.time()
    endpoint = "todoist_get_labels"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _log(endpoint, "error", (time.time() - start) * 1000, reason=limit_err["error"]["code"])
        return limit_err

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, deleted.", field="status")

    if is_favorite is not None and not isinstance(is_favorite, bool):
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'is_favorite' must be a boolean when provided.", field="is_favorite")

    if limit is None:
        limit = 50
    else:
        li = _as_int(limit)
        if li is None or li < 1 or li > 200:
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'limit' must be an integer between 1 and 200.", field="limit")
        limit = li

    if sort is None:
        sort = "order_index"
    else:
        if not isinstance(sort, str) or sort not in ("order_index", "created_at", "updated_at", "name"):
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'sort' must be one of: order_index, created_at, updated_at, name.", field="sort")

    if sort_direction is None:
        sort_direction = "asc"
    else:
        if not isinstance(sort_direction, str) or sort_direction not in ("asc", "desc"):
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'sort_direction' must be one of: asc, desc.", field="sort_direction")

    decoded = _decode_cursor(cursor)
    if decoded == "__bad__":
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    offset = 0
    if decoded:
        # enforce cursor consistency with current query to keep it opaque but safe
        expected_filter = {"status": status, "is_favorite": is_favorite}
        if decoded.get("sort") != sort or decoded.get("sort_direction") != sort_direction or decoded.get("filter") != expected_filter:
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match the current query parameters.", field="cursor")
        offset = decoded.get("offset", 0)

    labels = _load("todoist_labels.json")
    if not isinstance(labels, list):
        labels = []

    # Default behaviour: return only status != 'deleted' unless explicitly asked for deleted
    rows = []
    for r in labels:
        if not isinstance(r, dict):
            continue
        st = r.get("status")
        if status is None:
            if st == "deleted":
                continue
        else:
            if st != status:
                continue
        if is_favorite is not None and r.get("is_favorite") != is_favorite:
            continue
        rows.append(r)

    def _key(row):
        v = row.get(sort)
        # Normalize for stable ordering
        if sort in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort == "order_index":
            return v if isinstance(v, int) else 0
        if sort == "name":
            return (v or "").lower() if isinstance(v, str) else ""
        return v

    reverse = (sort_direction == "desc")
    rows.sort(key=lambda r: (_key(r), r.get("id", "")), reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        next_cursor = _encode_cursor(offset + limit, sort, sort_direction, {"status": status, "is_favorite": is_favorite})

    _log(endpoint, "ok", (time.time() - start) * 1000)
    return {
        "labels": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

