            if age <= day_s and isinstance(r.get("endpoint"), str) and r.get("endpoint", "").startswith("todoist_") and (
                "create_" in r.get("endpoint", "") or "update_" in r.get("endpoint", "") or "delete_" in r.get("endpoint", "") or "move_" in r.get("endpoint", "") or "bulk_" in r.get("endpoint", "")
            ):
                daily_writes += 1

        if recent >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=per_minute, window_seconds=window_s)
        if endpoint == "todoist_update_label" and daily_writes >= per_day_writes:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded.", quota=per_day_writes, window_seconds=day_s)
        return None

    start = time.time()
    endpoint = "todoist_update_label"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _log(endpoint, "error", (time.time() - start) * 1000, reason=limit_err["error"]["code"])
