    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, deleted.", field="status")

    labels = _load("todoist_labels.json")
    if not isinstance(labels, list):
        labels = []

    tid = todoist_label_id.strip()
    idx = None
    for i, r in enumerate(labels):
        if isinstance(r, dict) and r.get("todoist_label_id") == tid:
            idx = i
            break

    if idx is None:
        _log(endpoint, "error", (time.time() - start) * 1000, reason="NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.", todoist_label_id=tid)

    row = labels[idx]
    if not isinstance(row, dict):
        _log(endpoint, "error", (time.time() - start) * 1000, reason="NOT_FOUND")
        return _err("NOT_FOUND", "Label not found.", todoist_label_id=tid)

    # Enforce lifecycle + idempotency for delete
    current_status = row.get("status")
    if current_status not in ("active", "deleted"):
        current_status = "active"

    # If setting name, enforce unique among non-deleted labels
    if name is not None:
        nm = name.strip()
        for r in labels:
            if not isinstance(r, dict):
                continue
            if r is row:
                continue
            if r.get("status") != "deleted" and isinstance(r.get("name"), str) and r["name"].strip().lower() == nm.lower():
                _log(endpoint, "error", (time.time() - start) * 1000, reason="CONFLICT")
                return _err("CONFLICT", "A non-deleted label with this name already exists.", field="name")

    # Apply updates (only provided)
    changed = False
    now = _now()

    if name is not None and row.get("name") != name.strip():
        row["name"] = name.strip()
        changed = True
    if color is not None and row.get("color") != color:
        row["color"] = color
        changed = True
    if order_index is not None and row.get("order_index") != order_index:
        row["order_index"] = order_index
        changed = True
    if is_favorite is not None and row.get("is_favorite") != is_favorite:
        row["is_favorite"] = is_favorite
        changed = True

    if status is not None:
        if current_status == "deleted" and status == "active":
            # Allowed (schema transitions not declared for label in tool list, but business rules say restore via status).
            row["status"] = "active"
            row["deleted_at"] = None
            changed = True
        elif current_status == "active" and status == "deleted":
            row["status"] = "deleted"
            row["deleted_at"] = now
            changed = True
        elif current_status == status:
            # idempotent
            pass
        else:
            # Any other transition invalid
            _log(endpoint, "error", (time.time() - start) * 1000, reason="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition label from '{current_status}' to '{status}'.")

    # Enforce constraint: status = 'deleted' implies deleted_at not null, etc.
    if row.get("status") == "deleted" and not row.get("deleted_at"):
        row["deleted_at"] = now
        changed = True
    if row.get("status") != "deleted" and row.get("deleted_at") is not None:
        row["deleted_at"] = None
        changed = True

    if not changed:
        # No success without effect: return current row (read-only change) would be misleading; treat as no-op update allowed?
        # Real APIs typically return the resource even if unchanged; however contract forbids "success without effect" for mutations.
        # Here, the row exists but no fields changed: return VALIDATION_ERROR to force caller to send a change.
        _log(endpoint, "error", (time.time() - start) * 1000, reason="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No changes requested; provide at least one updatable field with a different value.")

    row["updated_at"] = now
    labels[idx] = row
    _save("todoist_labels.json", labels)

    _log(endpoint, "ok", (time.time() - start) * 1000)
    return {"label": row}

def todoist_delete_label(label_id, **_extra):
    import json, os, datetime, uuid, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0515000" if __import__("os").path.isdir("./environment_mix/0515000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        p = os.path.join(_DB, "todoist_request_logs.json")
        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limit_check():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_delete_label",
            "method": "WRITE",
            "status": status,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(label_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "label_id must be a string", label_id=label_id)
        if not re.match(r"^td_lbl_[A-Za-z0-9]+$", label_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "label_id does not match required pattern", label_id=label_id)

        labels = _load("todoist_labels.json")
        if not isinstance(labels, list):
            labels = []

        idx = None
        for i, l in enumerate(labels):
            if isinstance(l, dict) and l.get("id") == label_id:
                idx = i
                break
        if idx is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Label not found", label_id=label_id)

        row = labels[idx]
        if row.get("status") == "deleted":
            _log("CONFLICT")
            return _err("CONFLICT", "Label already deleted", label_id=label_id)

        now = _now_z()
        row["status"] = "deleted"
        row["deleted_at"] = now
        row["updated_at"] = now
        labels[idx] = row
        _save("todoist_labels.json", labels)

        _log("OK")
