    def _ensure_logs():
        os.makedirs(_DB, exist_ok=True)
        p = os.path.join(_DB, "todoist_request_logs.json")
        if not os.path.exists(p):
            _save("todoist_request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            s = ts[:-1] if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limit_check():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        rpm = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            d = (now_dt - ts).total_seconds()
            if 0 <= d <= 60:
                rpm += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        return None

    def _quota_check_write():
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        today = now_dt.date().isoformat()
        writes_today = 0
        for r in logs[-20000:]:
            if not isinstance(r, dict):
                continue
            if r.get("method") != "WRITE":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts.date().isoformat() == today:
                writes_today += 1
        if writes_today >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded", daily_write_quota=5000)
        return None

    def _log(status_s):
        _ensure_logs()
        logs = _load("todoist_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "td_rl_" + uuid.uuid4().hex[:16],
            "endpoint": "todoist_update_comment",
            "method": "WRITE",
            "status": status_s,
            "timestamp": _now_z(),
            "latency_ms": int((time.time() - _t0) * 1000)
        })
        _save("todoist_request_logs.json", logs)

    try:
        lim = _rate_limit_check()
        if lim:
            _log("RATE_LIMIT")
            return lim
        q = _quota_check_write()
        if q:
            _log("QUOTA_EXCEEDED")
            return q

        if not isinstance(comment_id, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "comment_id must be a string", comment_id=comment_id)
        if not re.match(r"^td_cmt_[A-Za-z0-9]+$", comment_id):
            # allow lookup to decide if it's real; if not found, return validation error per contract
            comments_tmp = _load("todoist_comments.json")
            if not isinstance(comments_tmp, list):
                comments_tmp = []
            if not any(isinstance(c, dict) and c.get("id") == comment_id for c in comments_tmp):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "comment_id does not match required pattern", comment_id=comment_id)

        if content is not None and (not isinstance(content, str) or content.strip() == ""):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be a non-empty string", field="content")
        if attachment is not None and not isinstance(attachment, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "attachment must be an object", field="attachment")
        if status is not None and status not in ("active", "deleted"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")

        comments = _load("todoist_comments.json")
        if not isinstance(comments, list):
            comments = []

        idx = None
        for i, c in enumerate(comments):
            if isinstance(c, dict) and c.get("id") == comment_id:
                idx = i
                break
        if idx is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Comment not found", comment_id=comment_id)

        row = comments[idx]
        if row.get("status") == "deleted":
            _log("CONFLICT")
            return _err("CONFLICT", "Cannot update a deleted comment", comment_id=comment_id)

        changed = False
        if content is not None and content != row.get("content"):
            row["content"] = content
            changed = True
        # schema for this cache has attachment but business rule says update content only; accept attachment updates as best-effort
        if attachment is not None and attachment != row.get("attachment"):
            row["attachment"] = attachment
            changed = True
        if status is not None:
            # allow soft-delete via status transition; consistent with lifecycle
            if status == "deleted":
                row["status"] = "deleted"
                row["deleted_at"] = _now_z()
                changed = True
            elif status == "active":
                # no restore transition declared; reject
                _log("INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Cannot transition comment to active", comment_id=comment_id, from_status=row.get("status"), to_status="active")

        if not changed:
            _log("OK")
            return {"comment": row}

        row["updated_at"] = _now_z()
        comments[idx] = row
        _save("todoist_comments.json", comments)

        _log("OK")
        return {"comment": row}
    except Exception as e:
        _log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

